package net.morben.shenggan;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import java.io.*;

public final class UpdateBackendChecks {
    static final Gson G=new Gson();static final Map<String,Boolean> checks=new LinkedHashMap<>();
    static void check(String name,boolean result){checks.put(name,result);System.out.println((result?"PASS ":"FAIL ")+name);}
    public static void main(String[] args)throws Exception{
        Path data=Path.of(args[0]);Files.createDirectories(data);Path run=data.resolve("game/versions/Fixture");Files.createDirectories(run.resolve("mods"));Path jar=run.resolve("mods/fixture.jar");
        try(ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(jar))){for(var file:Map.of("assets/qa/lang/en_us.json","{\"hello\":\"Hello %s\",\"ready\":\"Ready\",\"existing\":\"Done\",\"long\":\"A quest title\"}","assets/qa/lang/zh_cn.json","{\"existing\":\"已完成\"}").entrySet()){out.putNextEntry(new ZipEntry(file.getKey()));out.write(file.getValue().getBytes(java.nio.charset.StandardCharsets.UTF_8));out.closeEntry();}}
        byte[] original=Files.readAllBytes(jar);JsonObject input=new JsonObject();input.addProperty("runDirectory",run.toString());input.addProperty("id","Fixture");input.addProperty("version","1.20.1");input.addProperty("root",data.resolve("game").toString());input.addProperty("loader","Forge");
        Map<String,Object> scan=new NativeLocalization(input,data).scan(List.of(NativeResourceFiles.item(jar,"mods","QA",null,null,data)));input.addProperty("project",scan.get("project").toString());JsonObject source=G.toJsonTree(scan.get("sources")).getAsJsonArray().get(0).getAsJsonObject();String resource=source.get("id").getAsString();input.add("selected",G.toJsonTree(List.of(resource)));
        input.addProperty("limit",1);Map<String,Object> pending=new NativeLocalization(input,data).pending();check("pending-counts-all",((Number)pending.get("pending")).intValue()==3);JsonArray rows=G.toJsonTree(pending.get("entries")).getAsJsonArray();check("pending-limit",rows.size()==1);String identity=rows.get(0).getAsJsonObject().get("resource").getAsString()+"/"+rows.get(0).getAsJsonObject().get("id").getAsString();input.add("skip",G.toJsonTree(List.of(identity)));rows=G.toJsonTree(new NativeLocalization(input,data).pending().get("entries")).getAsJsonArray();check("pending-skips-attempted",!rows.get(0).getAsJsonObject().get("id").getAsString().equals(identity.substring(identity.indexOf('/')+1)));
        input.add("selected",new JsonArray());try{new NativeLocalization(input,data).pending();check("empty-selection-rejected",false);}catch(IOException e){check("empty-selection-rejected",true);}input.add("selected",G.toJsonTree(List.of(resource)));
        input.addProperty("onlyMissing",true);input.addProperty("origin","machine");input.add("changes",G.toJsonTree(List.of(Map.of("resource",resource,"entry","qa::hello","source","Hello %s","translation","你好 %s"),Map.of("resource",resource,"entry","qa::existing","source","Done","translation","不得覆盖"),Map.of("resource",resource,"entry","qa::ready","source","OLD SOURCE","translation","旧文本不得写入"))));Map<String,Object> saved=new NativeLocalization(input,data).save();check("automatic-saves-only-pending",((Number)saved.get("saved")).intValue()==1&&((Number)saved.get("skipped")).intValue()==2);
        input.addProperty("resource",resource);JsonArray entries=G.toJsonTree(new NativeLocalization(input,data).read().get("entries")).getAsJsonArray();JsonObject hello=null,existing=null;for(JsonElement e:entries){JsonObject row=e.getAsJsonObject();if(row.get("id").getAsString().equals("qa::hello"))hello=row;if(row.get("id").getAsString().equals("qa::existing"))existing=row;}
        check("machine-origin-recorded",hello.get("origin").getAsString().equals("machine"));check("embedded-Chinese-not-overwritten",existing.get("translation").getAsString().equals("已完成"));
        input.add("changes",G.toJsonTree(List.of(Map.of("resource",resource,"entry","qa::ready","source","Ready","translation","就绪 %s"))));saved=new NativeLocalization(input,data).save();check("unsafe-MT-refused-without-aborting",((Number)saved.get("saved")).intValue()==0&&((Number)saved.get("skipped")).intValue()==1);
        input.add("changes",G.toJsonTree(List.of(Map.of("resource",resource,"entry","qa::ready","source","Ready","translation","就绪"))));saved=new NativeLocalization(input,data).save();check("safe-MT-after-refusal",((Number)saved.get("saved")).intValue()==1);
        Map<String,Object> rescan=new NativeLocalization(input,data).scan(List.of(NativeResourceFiles.item(jar,"mods","QA",null,null,data)));input.addProperty("project",rescan.get("project").toString());entries=G.toJsonTree(new NativeLocalization(input,data).read().get("entries")).getAsJsonArray();check("machine-translation-survives-rescan",entries.toString().contains("你好 %s"));check("original-JAR-never-modified",Arrays.equals(original,Files.readAllBytes(jar)));
        check("join-domain",NativeBridge.validServer("play.example.com:25565").equals("play.example.com:25565"));check("join-IPv6",NativeBridge.validServer("[::1]:25565").contains("::1"));for(String address:List.of("https://evil","host:65536","host:bad","x\n:8","user@host")){try{NativeBridge.validServer(address);check("reject-join-"+address,false);}catch(IllegalArgumentException e){check("reject-join-"+address,true);}}
        var options=new org.jackhuang.hmcl.game.LaunchOptions.Builder().setQuickPlayOption(new org.jackhuang.hmcl.game.QuickPlayOption.MultiPlayer("localhost:25565")).create();check("HMCL-quickplay-options",options.getQuickPlayOption() instanceof org.jackhuang.hmcl.game.QuickPlayOption.MultiPlayer);
        String session=UUID.randomUUID().toString();Path world=run.resolve("saves/WorldAfterWindowClose");Files.createDirectories(world);try(NativePlayHistory history=new NativePlayHistory(data,session,run,ProcessHandle.current().pid())){Files.write(world.resolve("level.dat"),new byte[]{1,2,3});}
        JsonObject receipt=JsonParser.parseString(Files.readString(data.resolve("social/receipts/"+session.toUpperCase(Locale.ROOT)+".json"))).getAsJsonObject();check("engine-duration-receipt-finishes",receipt.get("finished").getAsBoolean()&&receipt.get("seconds").getAsDouble()>=0);check("engine-world-directory-recorded",receipt.get("world").getAsString().equals("WorldAfterWindowClose"));check("receipt-no-credentials",!receipt.toString().contains("token")&&!receipt.toString().contains("account"));
        long passed=checks.values().stream().filter(Boolean::booleanValue).count();Map<String,Object> report=Map.of("passed",passed,"failed",checks.size()-passed,"checks",checks);Files.writeString(data.getParent().resolve("update-backend-report.json"),G.toJson(report));if(passed!=checks.size())System.exit(1);
    }
}
